"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[96588],{96588:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/a-night-of-murder-without-a-perpetrator.png\\"\\n          title=\\"A Night of Murder Without a Perpetrator\\"\\n          author=\\"Keigo Higashino\\"\\n          publisher=\\"Random House Korea\\"\\n          publishedDate=\\"2009-04-16\\"\\n          isbn=\\"9788925532172\\"\\n          rating=3\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\nAn early short story collection by the author, it has one strong theme: how <mark>minor malice</mark> leads to catastrophic results.  \\nIt explores the ```banality of evil``` residing within ordinary people we commonly see around us, rather than a giant conspiracy or a psychopathic villain.  \\n<br>\\n<mark>A very small intent</mark> is tracked as it amplifies like a butterfly effect and leads to an irreversible tragedy.  \\nIt shows that even a seemingly ordinary and good human can harbor seeds of cruel destruction within.  \\n<br>\\nAs it is an early work of the author, some ```clumsiness``` in unrealistic setups or rough development can be felt."}')}}]);